    Route::post('/projects/{project}/corpuslab/{corpus}/decision', [CorpusLabController::class, 'decideProtocol'])->name('corpuslab.protocol.decision');
    Route::post('/projects/{project}/corpuslab/{corpus}/entries', [CorpusLabController::class, 'storeEntry'])->name('corpuslab.entries.store');
    Route::post('/projects/{project}/corpuslab/{corpus}/entries/{entry}/annotations', [CorpusLabController::class, 'annotate'])->name('corpuslab.annotations.store');
    Route::patch('/projects/{project}/corpuslab/{corpus}/entries/{entry}/status', [CorpusLabController::class, 'updateEntryStatus'])->name('corpuslab.entries.status');
    Route::delete('/projects/{project}/corpuslab/{corpus}/entries/{entry}', [CorpusLabController::class, 'destroyEntry'])->name('corpuslab.entries.destroy');
    Route::get('/projects/{project}/corpuslab/{corpus}/export', [CorpusLabController::class, 'export'])->name('corpuslab.export');
    Route::get('/projects/{project}/gurubahasa', [GuruBahasaController::class, 'index'])->name('gurubahasa.index');
    Route::get('/projects/{project}/gurubahasa/create', [GuruBahasaController::class, 'create'])->name('gurubahasa.create');
    Route::post('/projects/{project}/gurubahasa', [GuruBahasaController::class, 'store'])->name('gurubahasa.store');
    Route::get('/projects/{project}/gurubahasa/{material}', [GuruBahasaController::class, 'show'])->name('gurubahasa.show');
    Route::get('/projects/{project}/gurubahasa/{material}/edit', [GuruBahasaController::class, 'edit'])->name('gurubahasa.edit');
    Route::patch('/projects/{project}/gurubahasa/{material}', [GuruBahasaController::class, 'update'])->name('gurubahasa.update');
    Route::post('/projects/{project}/gurubahasa/{material}/curate', [GuruBahasaController::class, 'curate'])->name('gurubahasa.curate');
    Route::post('/projects/{project}/gurubahasa/{material}/publish', [GuruBahasaController::class, 'publish'])->name('gurubahasa.publish');
    Route::get('/projects/{project}/gurubahasa/{material}/export', [GuruBahasaController::class, 'export'])->name('gurubahasa.export');
    Route::delete('/projects/{project}/gurubahasa/{material}', [GuruBahasaController::class, 'destroy'])->name('gurubahasa.destroy');
    Route::get('/projects/{project}/litsynth', [LitSynthController::class, 'index'])->name('litsynth.index');
    Route::post('/projects/{project}/litsynth/sources', [LitSynthController::class, 'storeSource'])->name('litsynth.sources.store');
    Route::get('/projects/{project}/litsynth/sources/{source}', [LitSynthController::class, 'showSource'])->name('litsynth.sources.show');
    Route::put('/projects/{project}/litsynth/sources/{source}', [LitSynthController::class, 'updateSource'])->name('litsynth.sources.update');
    Route::post('/projects/{project}/litsynth/sources/{source}/verify', [LitSynthController::class, 'verifySource'])->name('litsynth.sources.verify');
    Route::post('/projects/{project}/litsynth/sources/{source}/extract', [LitSynthController::class, 'extractSource'])->name('litsynth.sources.extract');
    Route::get('/projects/{project}/litsynth/sources/{source}/download', [LitSynthController::class, 'downloadSource'])->name('litsynth.sources.download');
    Route::delete('/projects/{project}/litsynth/sources/{source}', [LitSynthController::class, 'destroySource'])->name('litsynth.sources.destroy');
    Route::post('/projects/{project}/litsynth/blueprints', [LitSynthController::class, 'storeBlueprint'])->name('litsynth.blueprints.store');
    Route::put('/projects/{project}/litsynth/blueprints/{blueprint}', [LitSynthController::class, 'updateBlueprint'])->name('litsynth.blueprints.update');
    Route::get('/projects/{project}/litsynth/blueprints/{blueprint}/validation', [ExpertValidationController::class, 'manage'])->name('litsynth.validation.manage');
    Route::post('/projects/{project}/litsynth/blueprints/{blueprint}/versions/{version}/invitations', [ExpertValidationController::class, 'createInvitation'])->name('litsynth.validation.invitations.store');
    Route::delete('/projects/{project}/litsynth/blueprints/{blueprint}/invitations/{invitation}', [ExpertValidationController::class, 'revokeInvitation'])->name('litsynth.validation.invitations.destroy');
    Route::get('/assignments/{assignment}', [WritingAssignmentController::class, 'show'])->name('assignments.show');
    Route::patch('/assignments/{assignment}', [WritingAssignmentController::class, 'update'])->name('assignments.update');
    Route::post('/assignments/{assignment}/revisions', [WritingAssignmentController::class, 'submit'])->name('assignments.revisions.store');
    Route::post('/revisions/{revision}/feedback/generate', [WritingAssignmentController::class, 'generateFeedback'])->middleware('throttle:3,1')->name('feedback.generate');
    Route::post('/revisions/{revision}/feedback', [WritingAssignmentController::class, 'createFeedback'])->name('feedback.store');
    Route::patch('/feedback/{report}', [WritingAssignmentController::class, 'editFeedback'])->name('feedback.update');
    Route::post('/feedback/{report}/publish', [WritingAssignmentController::class, 'publishFeedback'])->name('feedback.publish');
});
